inline const wchar_t* Tr(const wchar_t* text) {
  if (!g_ui_lang || !text) return text;
  for (const auto& e : kUiText) if (wcscmp(text, e.en) == 0) return e.zh;
  return text;
}

inline std::wstring Tr(std::wstring text) {
  if (!g_ui_lang) return text;
  for (const auto& e : kUiText) if (text == e.en) return e.zh;
  return text;
}
